import { GoogleGenAI, Type } from "@google/genai";

// Initialize Gemini Client
// Note: In a production app, ensure the API key is strictly backend-managed or properly proxied.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

// Models
const TEXT_MODEL = 'gemini-3-flash-preview'; 
const VISION_MODEL = 'gemini-2.5-flash-image'; // Using generic image model for receipt analysis validation or extraction

/**
 * Orchestrates a travel request from natural language.
 * E.g., "I need to go to London next week for a 3-day conference."
 */
export const orchestrateTravelRequest = async (prompt: string): Promise<any> => {
  if (!process.env.API_KEY) {
    console.warn("API Key missing");
    return null;
  }

  try {
    const response = await ai.models.generateContent({
      model: TEXT_MODEL,
      contents: `Extract travel details from the following request. 
      Today is ${new Date().toISOString().split('T')[0]}.
      Calculate specific dates if relative dates (like "next Friday") are used.

      Request: "${prompt}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            destination_city: { type: Type.STRING },
            destination_country: { type: Type.STRING },
            departure_date: { type: Type.STRING, description: "YYYY-MM-DD format" },
            return_date: { type: Type.STRING, description: "YYYY-MM-DD format" },
            purpose: { type: Type.STRING },
            estimated_budget: { type: Type.NUMBER },
            summary: { type: Type.STRING, description: "A professional summary of the trip" },
          },
          required: ["destination_city", "summary"],
        },
      },
    });

    const text = response.text;
    if (!text) return null;
    return JSON.parse(text);
  } catch (error) {
    console.error("Orchestration error:", error);
    throw error;
  }
};

/**
 * Analyzes a receipt image to extract expense details.
 */
export const analyzeReceipt = async (base64Image: string): Promise<any> => {
  if (!process.env.API_KEY) return null;

  try {
    // Clean base64 string if it contains metadata header
    const cleanBase64 = base64Image.split(',')[1] || base64Image;

    const response = await ai.models.generateContent({
      model: TEXT_MODEL, // Using V3 Flash as it is multimodal capable and supports schema well
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg', // Assuming jpeg for simplicity, or detect from input
              data: cleanBase64,
            },
          },
          {
            text: "Analyze this receipt and extract the merchant name, date, total amount, and line items.",
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            merchant: { type: Type.STRING },
            date: { type: Type.STRING, description: "YYYY-MM-DD" },
            total: { type: Type.NUMBER },
            category: { type: Type.STRING, description: "Best guess category e.g., Meals, Transport, Hotel" },
            line_items: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  description: { type: Type.STRING },
                  amount: { type: Type.NUMBER },
                },
              },
            },
          },
        },
      },
    });

    const text = response.text;
    if (!text) return null;
    return JSON.parse(text);
  } catch (error) {
    console.error("Receipt analysis error:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { TravelRequestData } from '../types';
import { orchestrateTravelRequest } from '../services/geminiService';
import { Sparkles, Plane, MapPin, Calendar, Briefcase, Loader2, CheckCircle } from 'lucide-react';

const TravelRequest: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [aiPrompt, setAiPrompt] = useState('');
  const [formData, setFormData] = useState<TravelRequestData>({
    requestName: '',
    description: '',
    projectCurrency: 'USD',
    budget: 0,
    travelToCountry: '',
    travelToCity: '',
    travelDate: '',
    returnDate: '',
    purpose: 'Business',
    accommodationType: 'Hotel',
    isUrgent: false,
  });

  const handleAiOrchestrate = async () => {
    if (!aiPrompt.trim()) return;
    setLoading(true);
    try {
      const result = await orchestrateTravelRequest(aiPrompt);
      if (result) {
        setFormData(prev => ({
          ...prev,
          travelToCity: result.destination_city || prev.travelToCity,
          travelToCountry: result.destination_country || prev.travelToCountry,
          travelDate: result.departure_date || prev.travelDate,
          returnDate: result.return_date || prev.returnDate,
          description: result.summary || prev.description,
          requestName: `Travel to ${result.destination_city || 'Destination'}`,
          budget: result.estimated_budget || prev.budget,
        }));
      }
    } catch (e) {
      console.error("AI Error", e);
      alert("Failed to orchestrate request. Please check API key or try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value, type } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? (e.target as HTMLInputElement).checked : value
    }));
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500">

      {/* Left Panel: Navigation/Sections (Visual only for demo) */}
