          <div className="p-4 text-gray-600 hover:bg-gray-50 cursor-pointer">Notes and Attachments</div>
          <div className="p-4 text-gray-600 hover:bg-gray-50 cursor-pointer">Travel Details</div>
          <div className="p-4 text-gray-600 hover:bg-gray-50 cursor-pointer">Suppliers</div>
        </div>
      </div>

      {/* Main Content */}
      <div className="lg:col-span-9 space-y-6">

        {/* AI Orchestration Bar */}
        <div className="bg-gradient-to-r from-indigo-600 to-blue-500 p-6 rounded-xl shadow-lg text-white">
          <div className="flex items-center gap-2 mb-3">
            <Sparkles className="text-yellow-300" />
            <h2 className="text-lg font-semibold">AI Travel Assistant</h2>
          </div>
          <p className="text-blue-100 text-sm mb-4">
            Describe your trip (e.g., "I need to visit the New York office for a strategy meeting from March 10th to 14th") and let AI fill the details.
          </p>
          <div className="flex gap-2">
            <input 
              type="text" 
              value={aiPrompt}
              onChange={(e) => setAiPrompt(e.target.value)}
