export default TravelRequest;

import React, { useState, useRef } from 'react';
import { ExpenseItem } from '../types';
import { analyzeReceipt } from '../services/geminiService';
import { UploadCloud, Receipt, Plus, Trash2, Loader2, Camera } from 'lucide-react';

const ExpenseClaim: React.FC = () => {
  const [analyzing, setAnalyzing] = useState(false);
  const [items, setItems] = useState<ExpenseItem[]>([
    { id: '1', date: '2026-02-11', description: 'Hotel Expenses', category: 'Accommodation', amount: 450.00, merchant: 'Hilton' },
    { id: '2', date: '2026-02-12', description: 'Uber to Airport', category: 'Transport', amount: 45.50, merchant: 'Uber' },
  ]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setAnalyzing(true);

    // Convert to Base64
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64String = reader.result as string;
      try {
        const result = await analyzeReceipt(base64String);
        if (result) {
          const newItem: ExpenseItem = {
            id: Date.now().toString(),
            date: result.date || new Date().toISOString().split('T')[0],
            description: result.line_items?.[0]?.description || 'Expense Item',
            category: result.category || 'General',
            amount: result.total || 0,
            merchant: result.merchant || 'Unknown Merchant'
          };
          setItems(prev => [...prev, newItem]);
        }
      } catch (err) {
        console.error("Receipt Analysis Failed", err);
        alert("Could not analyze receipt. Please try again.");
      } finally {
        setAnalyzing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const triggerUpload = () => fileInputRef.current?.click();

  const totalClaim = items.reduce((sum, item) => sum + item.amount, 0);

  return (
    <div className="space-y-6 animate-in fade-in zoom-in-95 duration-500">

      {/* Header */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Expense Claim: #EXP-2026-004</h1>
          <p className="text-sm text-gray-500">Project: Business Trip to Mumbai</p>
        </div>
        <div className="text-right">
          <p className="text-sm text-gray-500">Total Claim Amount</p>
          <p className="text-3xl font-bold text-blue-600">${totalClaim.toFixed(2)}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Upload Area */}
        <div className="lg:col-span-1">
          <div 
            className={`border-2 border-dashed rounded-xl p-8 flex flex-col items-center justify-center text-center h-64 transition-colors ${analyzing ? 'bg-blue-50 border-blue-400' : 'border-gray-300 hover:border-blue-400 hover:bg-gray-50 cursor-pointer'}`}
            onClick={triggerUpload}
          >
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept="image/*" 
              onChange={handleFileUpload}
            />
            {analyzing ? (
              <div className="flex flex-col items-center">
                <Loader2 className="animate-spin text-blue-600 mb-4" size={48} />
                <p className="font-medium text-blue-700">Analyzing Receipt...</p>
                <p className="text-xs text-blue-500 mt-2">Extracting Merchant, Date & Total</p>
              </div>
            ) : (
              <>
                <div className="bg-blue-100 p-4 rounded-full mb-4">
                  <Camera className="text-blue-600" size={32} />
                </div>
                <h3 className="text-lg font-medium text-gray-900">Scan Receipt</h3>
                <p className="text-sm text-gray-500 mt-2">Click to upload image or drag and drop</p>
                <p className="text-xs text-gray-400 mt-4">Supports JPG, PNG (AI Powered)</p>
              </>
            )}
          </div>

          <div className="mt-4 bg-yellow-50 p-4 rounded-lg border border-yellow-200">
            <p className="text-xs text-yellow-800">
              <strong>Tip:</strong> Uploading a receipt automatically populates the line items using Google Gemini Vision AI.
            </p>
          </div>
        </div>

        {/* Line Items */}
        <div className="lg:col-span-2 bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
          <div className="p-4 border-b border-gray-200 flex justify-between items-center bg-gray-50">
            <h3 className="font-semibold text-gray-700 flex items-center gap-2">
              <Receipt size={18} /> Line Items
            </h3>
            <button className="text-blue-600 text-sm font-medium hover:underline flex items-center gap-1">
              <Plus size={16} /> Add Manually
            </button>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead className="text-xs text-gray-700 uppercase bg-gray-50 border-b">
                <tr>
                  <th className="px-6 py-3">Date</th>
                  <th className="px-6 py-3">Merchant</th>
                  <th className="px-6 py-3">Category</th>
                  <th className="px-6 py-3">Description</th>
                  <th className="px-6 py-3 text-right">Amount</th>
                  <th className="px-6 py-3 text-center">Action</th>
                </tr>
              </thead>
              <tbody>
                {items.map((item) => (
                  <tr key={item.id} className="bg-white border-b hover:bg-gray-50">
                    <td className="px-6 py-4 font-medium text-gray-900">{item.date}</td>
                    <td className="px-6 py-4">{item.merchant}</td>
                    <td className="px-6 py-4">
                      <span className="bg-blue-100 text-blue-800 text-xs font-medium px-2.5 py-0.5 rounded">
                        {item.category}
                      </span>
                    </td>
                    <td className="px-6 py-4">{item.description}</td>
                    <td className="px-6 py-4 text-right">${item.amount.toFixed(2)}</td>
                    <td className="px-6 py-4 text-center">
                      <button className="text-red-500 hover:text-red-700">
                        <Trash2 size={16} />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {items.length === 0 && (
            <div className="p-8 text-center text-gray-500">
              No expenses added yet. Upload a receipt to start.
            </div>
          )}
        </div>

      </div>
    </div>
  );
};

export default ExpenseClaim;

