                  <th className="px-4 py-3">Merchant</th>
                  <th className="px-4 py-3">Category</th>
                  <th className="px-4 py-3">Amount (₹)</th>
                  <th className="px-4 py-3 text-center">Recurring</th>
                  <th className="px-4 py-3 text-center">Action</th>
