  const handleNewRequest = () => {
      setFormData({
        requestName: '',
        description: '',
        projectCurrency: 'INR',
        budget: 0,
        travelToCountry: '',
        travelToCity: '',
        travelDate: '',
        returnDate: '',
        purpose: 'Business',
        accommodationType: 'Hotel',
        isUrgent: false,
        attendees: '',
        accommodationPreference: '',
        notes: '',
        attachments: [],
        selectedSupplier: ''
