import React, { useState, useRef } from 'react';
import { ExpenseItem } from '../types';
import { analyzeReceipt, generateExpenseSummary } from '../services/geminiService';
import { UploadCloud, Receipt, Plus, Trash2, Loader2, Camera, Repeat, Calendar, FileText, Sparkles, CreditCard, MapPin } from 'lucide-react';

const EXPENSE_CATEGORIES = ['Meals', 'Transport', 'Accommodation', 'Flights', 'Supplies', 'Entertainment', 'General'];

const formatCurrency = (amount: number, currencyCode: string = 'INR') => {
    return new Intl.NumberFormat('en-IN', { style: 'currency', currency: currencyCode }).format(amount);
};

const ExpenseClaim: React.FC = () => {
  const [analyzing, setAnalyzing] = useState(false);
  const [generatingSummary, setGeneratingSummary] = useState(false);
  const [aiSummary, setAiSummary] = useState<string | null>(null);
  const [items, setItems] = useState<ExpenseItem[]>([
    { id: '1', date: '2026-02-11', description: 'Hotel Expenses', category: 'Accommodation', amount: 4500.00, taxAmount: 500, currency: 'INR', merchant: 'Hilton', isRecurring: false, vendorAddress: 'Mumbai, India', paymentMethod: 'Corp Card' },
    { id: '2', date: '2026-02-12', description: 'Uber to Airport', category: 'Transport', amount: 450.50, taxAmount: 20, currency: 'INR', merchant: 'Uber', isRecurring: true, vendorAddress: 'Mumbai', paymentMethod: 'Visa 4242' },
  ]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setAnalyzing(true);

    // Convert to Base64
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64String = reader.result as string;
      const mimeType = file.type || 'image/jpeg';

      try {
        const result = await analyzeReceipt(base64String, mimeType);
        if (result) {
          const newItem: ExpenseItem = {
            id: Date.now().toString(),
            date: result.date || new Date().toISOString().split('T')[0],
            description: result.line_items?.[0]?.description || 'Expense Item',
            category: EXPENSE_CATEGORIES.includes(result.category) ? result.category : 'General',
            amount: result.total || 0,
            taxAmount: result.tax_amount || 0,
            currency: result.currency || 'INR',
            merchant: result.merchant || 'Unknown Merchant',
            vendorAddress: result.vendor_address || '',
            paymentMethod: result.payment_method || '',
            isRecurring: false
          };
          setItems(prev => [...prev, newItem]);
        }
      } catch (err) {
        console.error("Receipt Analysis Failed", err);
        alert("Could not analyze receipt/document. Please try again.");
      } finally {
        setAnalyzing(false);
        // Reset input
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsDataURL(file);
  };

  const updateItem = (id: string, field: keyof ExpenseItem, value: any) => {
      setItems(prev => prev.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const deleteItem = (id: string) => {
      setItems(prev => prev.filter(item => item.id !== id));
  };

  const addItemManually = () => {
      const newItem: ExpenseItem = {
          id: Date.now().toString(),
          date: new Date().toISOString().split('T')[0],
          description: 'New Expense',
          category: 'General',
          amount: 0,
          taxAmount: 0,
          currency: 'INR',
          merchant: '',
          isRecurring: false
      };
      setItems([...items, newItem]);
  };

  const handleGenerateSummary = async () => {
      if (items.length === 0) return;
      setGeneratingSummary(true);
      const summary = await generateExpenseSummary(items);
      setAiSummary(summary);
      setGeneratingSummary(false);
  };

  const triggerUpload = () => fileInputRef.current?.click();

  const openDatePicker = (id: string) => {
    const element = document.getElementById(id) as HTMLInputElement;
    if(element) {
        if (typeof (element as any).showPicker === 'function') {
            (element as any).showPicker();
        } else {
            element.focus();
        }
    }
  }

  const totalClaim = items.reduce((sum, item) => sum + item.amount, 0);

  return (
    <div className="space-y-6 animate-in fade-in zoom-in-95 duration-500">

      {/* Header */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Expense Claim: #EXP-2026-004</h1>
          <p className="text-sm text-gray-500">Project: Business Trip to Mumbai</p>
        </div>
