  const [items, setItems] = useState<ExpenseItem[]>([
    { id: '1', date: '2026-02-11', description: 'Hotel Expenses', category: 'Accommodation', amount: 4500.00, taxAmount: 500, currency: 'INR', merchant: 'Hilton', isRecurring: false, vendorAddress: 'Mumbai, India', paymentMethod: 'Corp Card' },
    { id: '2', date: '2026-02-12', description: 'Uber to Airport', category: 'Transport', amount: 450.50, taxAmount: 20, currency: 'INR', merchant: 'Uber', isRecurring: true, vendorAddress: 'Mumbai', paymentMethod: 'Visa 4242' },
  ]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setAnalyzing(true);

    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64String = reader.result as string;
      const mimeType = file.type || 'image/jpeg';

      try {
        const result = await analyzeReceipt(base64String, mimeType);
        if (result) {
          const newItem: ExpenseItem = {
            id: Date.now().toString(),
            date: result.date || new Date().toISOString().split('T')[0],
            description: result.line_items?.[0]?.description || 'Expense Item',
            category: EXPENSE_CATEGORIES.includes(result.category) ? result.category : 'General',
            amount: result.total || 0,
            taxAmount: result.tax_amount || 0,
            currency: result.currency || 'INR',
            merchant: result.merchant || 'Unknown Merchant',
            vendorAddress: result.vendor_address || '',
            paymentMethod: result.payment_method || '',
            isRecurring: false
          };
          setItems(prev => [...prev, newItem]);
        }
      } catch (err) {
        console.error("Receipt Analysis Failed", err);
        alert("Could not analyze receipt/document. Please try again.");
      } finally {
        setAnalyzing(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsDataURL(file);
  };

  const updateItem = (id: string, field: keyof ExpenseItem, value: any) => {
      setItems(prev => prev.map(item => item.id === id ? { ...item, [field]: value } : item));
